<style scoped>
.codename-logo {
  display: block;
  flex-shrink: 0;
  max-width: 100%;
  color: var(--ds-color-on-surface);
}

/* Cor dinamica: fundo claro → preto, fundo escuro → branco */
:global([data-mode='light']) .codename-logo {
  color: #000000;
}

:global([data-mode='dark']) .codename-logo {
  color: #ffffff;
}

/* Fallback: sem data-mode definido ainda, herda do system preference */
@media (prefers-color-scheme: dark) {
  :global(html:not([data-mode])) .codename-logo {
    color: #ffffff;
  }
}
</style>
